{
  "name": "@danieldeusing/seedr",
  "version": "0.1.183",
  "description": "Seed your projects with AI configurations",
  "type": "module",
  "bin": {
    "seedr": "dist/cli.js"
  },
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsup",
    "dev": "tsx src/cli.ts",
    "typecheck": "tsc --noEmit",
    "lint": "eslint src/",
    "lint:fix": "eslint src/ --fix",
    "clean": "rm -rf dist",
    "test": "vitest run",
    "test:watch": "vitest",
    "test:coverage": "vitest run --coverage"
  },
  "dependencies": {
    "@clack/prompts": "^1.0.1",
    "chalk": "^5.3.0",
    "commander": "^14.0.0",
    "ora": "^9.0.0"
  },
  "devDependencies": {
    "@seedr/registry-ops": "workspace:*",
    "@seedr/shared": "workspace:*",
    "@types/node": "^25.0.0",
    "@vitest/coverage-v8": "^4.1.11",
    "memfs": "^4.14.0",
    "tsup": "^8.3.0",
    "tsx": "^4.19.0",
    "typescript": "^5.7.0",
    "vitest": "^4.1.11"
  },
  "keywords": [
    "ai",
    "claude",
    "copilot",
    "antigravity",
    "codex",
    "opencode",
    "configuration",
    "seeder"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/danieldeusing/seedr.git"
  },
  "homepage": "https://seedr.danieldeusing.de",
  "bugs": {
    "url": "https://github.com/danieldeusing/seedr/issues"
  },
  "license": "MIT"
}
